function showToast(message){if(!toast)return;window.clearTimeout(toastTimer);toast.textContent=message;toast.classList.add('visible');toastTimer=window.setTimeout(()=>toast.classList.remove('visible'),3200);}
function persistAccess(){try{localStorage.setItem(ACCESS_KEY,'true');}catch{}}
function readConsent(){try{return localStorage.getItem(CONSENT_KEY)===TERMS_VERSION;}catch{return false;}}
function persistConsent(){try{localStorage.setItem(CONSENT_KEY,TERMS_VERSION);}catch{}}
function haptic(kind){try{const hb=window.Telegram?.WebApp?.HapticFeedback;if(!hb)return;if(kind==='success'||kind==='error'||kind==='warning')hb.notificationOccurred(kind);else hb.impactOccurred(kind||'light');}catch{}}
function viewClass(){if(state.dir==='forward')return 'view-enter view-enter-forward';if(state.dir==='back')return 'view-enter view-enter-back';return 'view-enter';}
function scrollTopInstant(){try{const el=document.documentElement;const prev=el.style.scrollBehavior;el.style.scrollBehavior='auto';el.scrollTop=0;if(document.body)document.body.scrollTop=0;el.style.scrollBehavior=prev||'';}catch{}}
function motionOK(){try{return window.matchMedia&&window.matchMedia('(prefers-reduced-motion: no-preference)').matches;}catch{return false;}}
function flowProgress(step){const segs=[1,2,3].map(i=>`<span class="flow-seg${i<=step?' on':''}"${i===step?' aria-current="step"':''}></span>`).join('');return `<div class="flow-progress" role="group" aria-label="Шаг ${step} из 3">${segs}</div>`;}
