function renderRewards(){return `<section class="${viewClass()}"><div class="detail-topbar"><button class="icon-button" type="button" data-action="back-step" aria-label="Назад">${icon('arrowLeft',19)}</button><div class="eyebrow">Шаг 02</div></div>${flowProgress(2)}<div class="reward-intro"><div class="eyebrow">Выбор уровня</div><h1 class="view-heading">Какую награду<br />выбираешь?</h1><p class="view-subheading">Выбери подходящий вариант. После этого откроется инструкция и ссылка на задание.</p></div><div class="reward-list"><button class="reward-option" type="button" data-action="choose-reward" data-reward="small"><span class="reward-option-copy"><span>Вариант 01 · Дебетовая карта</span><strong>до 2 000 ₽</strong><small>Более доступный</small></span><span class="reward-option-mark">${icon('arrowRight',19)}</span></button><button class="reward-option" type="button" data-action="choose-reward" data-reward="large"><span class="reward-option-copy"><span>Вариант 02 · Кредитная карта</span><strong>до 4 000 ₽</strong><small>Менее доступный <b class="age-badge">18+</b></small></span><span class="reward-option-mark">${icon('arrowRight',19)}</span></button></div></section>`;}
function renderAgeGate(){return `<section class="${viewClass()} age-gate-view"><div class="detail-topbar"><button class="icon-button" type="button" data-action="back-step" aria-label="Назад">${icon('arrowLeft',19)}</button><div class="eyebrow">Проверка возраста</div></div><div class="info-card age-gate-card"><div class="detail-hero-icon">${icon('shield',30)}</div><h1>Вам уже исполнилось 18 лет?</h1><p>Этот вариант доступен только пользователям 18 лет и старше.</p><div class="gate-actions"><button class="button button-full" type="button" data-action="age-yes">Да, мне 18+</button><button class="button button-outline button-full" type="button" data-action="age-no">Нет, мне нет 18</button></div></div></section>`;}
function renderInstructions(){const reward=rewards[state.selectedReward]||rewards.small;const plan=instructionPlans[reward.id]||instructionPlans.small;const steps=plan.steps.map((step,index)=>`<li class="step-item"><span class="step-number">${String(index+1).padStart(2,'0')}</span><p>${escapeHTML(step)}</p></li>`).join('');return `<section class="${viewClass()}"><div class="detail-topbar"><button class="icon-button" type="button" data-action="back-step" aria-label="Назад">${icon('arrowLeft',19)}</button><div class="eyebrow">Шаг 03</div></div>${flowProgress(3)}<div class="instruction-heading"><div class="eyebrow">Пошаговая инструкция</div><h1 class="view-heading">Почти готово<br />к старту.</h1><span class="selected-reward">${icon('wallet',14)} ${escapeHTML(plan.product)} · награда ${escapeHTML(reward.label)}</span></div><div class="info-card"><h2>${icon('check',19)} Что нужно сделать</h2><p>Пять шагов: оформить карту по ссылке, принять доставку, активировать её покупкой и написать отзыв в личном кабинете. Награда поступит на карту после проверки отзыва.</p><ol class="step-list">${steps}</ol>${plan.note?`<div class="step-note">${icon('info',15)}<p>${escapeHTML(plan.note)}</p></div>`:''}</div><div class="detail-actions"><a class="button button-full" href="${reward.link}" target="_blank" rel="noopener noreferrer" data-action="start-task" data-reward="${reward.id}">Перейти к заданию ${icon('arrowUpRight',17)}</a><button class="button button-ghost button-full" type="button" data-action="back-step">Выбрать другой уровень</button></div><div class="external-hint">${icon('link',13)} Ссылка откроется в новой вкладке</div></section>`;}
function activeTaskById(taskId){return state.activeTasks.find(task=>task.id===taskId)||null;}
function taskStage(task){return task&&task.stage==='under-review'?'under-review':'progress';}
function reviewIsValid(value){return String(value||'').trim().replace(/\s+/g,' ').length>=REVIEW_MIN_LENGTH;}
function renderActiveTask(task){const reward=rewards[task.rewardId]||rewards.small;const plan=instructionPlans[reward.id]||instructionPlans.small;const underReview=taskStage(task)==='under-review';return `<article class="active-task-card"><div class="active-task-top"><span class="active-task-icon">${icon('reviews',20)}</span><div class="active-task-copy"><h3>${escapeHTML(task.title||'Отзывы')}</h3><p>${escapeHTML(plan.product)} · добавлено ${escapeHTML(formatDate(task.createdAt))}</p></div><span class="task-status${underReview?' is-review':''}">${underReview?'Отзыв на проверке':'В процессе'}</span></div>${underReview?`<div class="task-review-block">${icon('quote',15)}<div><span>Твой отзыв</span><p>${escapeHTML(task.review||'')}</p></div></div>`:''}<div class="active-task-bottom"><span class="active-task-reward">Награда: <strong>${escapeHTML(reward.label)}</strong></span><a class="button button-ghost" href="${reward.link}" target="_blank" rel="noopener noreferrer">Продолжить ${icon('arrowUpRight',14)}</a></div>${underReview?`<div class="task-waiting">${icon('clock',16)}<span>Отзыв проверяется: награда поступит на карту в течение 3-4 дней.</span></div>`:`<div class="active-task-actions"><button class="button button-full" type="button" data-action="task-done" data-task="${escapeHTML(task.id)}">${icon('check',17)} Выполнил</button><p class="active-task-hint">Нажми «Выполнил», когда карта оформлена, доставлена и активирована покупкой от 1 ₽</p></div>`}</article>`;}
function renderModalSheet(content){return `<div class="modal-overlay" data-action="close-modal"><div class="modal-sheet" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-grabber" aria-hidden="true"></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Закрыть">${icon('close',16)}</button>${content}</div></div>`;}
function renderModal(){const modal=state.modal;if(!modal)return '';
 if(modal.type==='waiting'){return renderModalSheet(`<div class="modal-icon is-success">${icon('check',26)}</div><div class="modal-kicker">Отзыв отправлен</div><h2 class="modal-title" id="modal-title">Отзыв проверяется</h2><p class="modal-text">Награда скоро будет у вас: мы проверим отзыв и отправим вознаграждение на карту. Обычно это занимает 3-4 дня.</p><div class="modal-note is-success">${icon('spark',15)}<span>Статус задания уже обновлён в личном кабинете.</span></div><div class="modal-actions"><button class="button button-full" type="button" data-action="close-modal">Готово</button></div>`);}
 if(modal.type==='legal'){return renderModalSheet(`<div class="modal-icon is-muted">${icon('shield',26)}</div><div class="modal-kicker">Неофициальный сервис · важно</div><h2 class="modal-title" id="modal-title">Правовая информация</h2><div class="legal-doc">${renderLegalDoc()}</div>`);}
 if(modal.type==='terms'){return renderModalSheet(`<div class="modal-icon is-muted">${icon('shield',26)}</div><div class="modal-kicker">Документ сервиса · юридически значимая редакция</div><h2 class="modal-title" id="modal-title">Соглашение с условиями сервиса</h2><div class="legal-doc">${renderTermsDoc()}</div>`);}
 if(modal.type==='privacy'){return renderModalSheet(`<div class="modal-icon is-muted">${icon('shield',26)}</div><div class="modal-kicker">Документ сервиса</div><h2 class="modal-title" id="modal-title">Политика конфиденциальности</h2><div class="legal-doc">${renderPrivacyDoc()}</div>`);}
 const task=activeTaskById(modal.taskId);if(!task)return '';const reward=rewards[task.rewardId]||rewards.small;const plan=instructionPlans[reward.id]||instructionPlans.small;
 if(modal.type==='done'){return renderModalSheet(`<div class="modal-icon">${icon('check',26)}</div><div class="modal-kicker">Проверка условий</div><h2 class="modal-title" id="modal-title">Ты получил карту и совершил с ней покупку?</h2><p class="modal-text">Для награды нужно оформить ${escapeHTML(reward.productAccusative)} по ссылке, принять доставку и активировать её любой покупкой от 1 рубля. Переводы не считаются.</p><div class="modal-actions"><button class="button button-full" type="button" data-action="done-yes">Да, всё выполнено</button><button class="button button-outline button-full" type="button" data-action="done-no">Нет, ещё нет</button></div>`);}
 if(modal.type==='wait'){return renderModalSheet(`<div class="modal-icon is-muted">${icon('clock',26)}</div><div class="modal-kicker">Пока рано</div><h2 class="modal-title" id="modal-title">Нужно дождаться выполнения условий</h2><p class="modal-text">Награда начисляется только после того, как ${escapeHTML(plan.product.toLowerCase())} оформлена по ссылке, доставлена и активирована покупкой от 1 рубля. Переводы не считаются.</p><div class="modal-note">${icon('info',15)}<span>Вернись в личный кабинет и нажми «Выполнил» снова, когда карта будет активирована.</span></div><div class="modal-actions"><a class="button button-full" href="${reward.link}" target="_blank" rel="noopener noreferrer">${escapeHTML(plan.cta)} ${icon('arrowUpRight',16)}</a><button class="button button-ghost button-full" type="button" data-action="close-modal">Понятно, продолжу позже</button></div>`);}
 if(modal.type==='review'){return renderModalSheet(`<div class="modal-icon">${icon('quote',26)}</div><div class="modal-kicker">Условия выполнены</div><h2 class="modal-title" id="modal-title">Напиши отзыв под заданием</h2><p class="modal-text">Расскажи, как прошли оформление, доставка и активация карты. Отзыв появится в личном кабинете под этим заданием.</p><label class="review-field" for="review-text"><span>Твой отзыв</span><textarea class="review-input" id="review-text" name="review" rows="5" maxlength="1200" placeholder="Например: оформил карту за пару минут, курьер привёз в удобное время, активировал покупкой на 1 ₽ в тот же день…">${escapeHTML(modal.draft||'')}</textarea></label><div class="modal-actions"><button class="button button-full" type="button" data-action="submit-review">Прикрепить отзыв ${icon('arrowRight',16)}</button><button class="button button-ghost button-full" type="button" data-action="close-modal">Отмена</button></div>`);}
 return '';}
function renderAccount(){const displayName=getDisplayName(user),username=getUsername(user),tasks=state.activeTasks,profileLabel=user.isTelegram?'Профиль Telegram':'Демо-профиль';return `<section class="${viewClass()}" aria-labelledby="account-heading"><div class="account-heading"><div class="eyebrow">Личный кабинет</div><h1 class="view-heading" id="account-heading">Твой профиль</h1><p class="view-subheading">Здесь собраны данные профиля и задания, которые ты уже начал.</p></div><div class="profile-card">${avatarMarkup(user,'large')}<div class="profile-card-copy"><span class="profile-label">${profileLabel}</span><h2>${escapeHTML(displayName)}</h2><p>${escapeHTML(username)}</p></div></div><div class="account-section"><div class="account-section-heading"><h2>Задания в процессе</h2><span class="task-count">${tasks.length}</span></div>${tasks.length?tasks.map(renderActiveTask).join(''):`<div class="empty-state"><div class="empty-state-icon">${icon('clock',21)}</div><h3>Пока здесь пусто</h3><p>Выбери задание на главной, чтобы оно появилось в этом разделе.</p></div>`}</div><div class="account-footnote">${icon('shield',14)}<span>Данные профиля берутся из Telegram Mini App. В обычном браузере показан демо-профиль.</span></div></section>`;}
function renderBottomNav(){const onAccount=state.view==='account',tasksCount=state.activeTasks.length;return `<nav class="bottom-nav" aria-label="Основная навигация"><button class="nav-item${onAccount?'':' active'}" type="button" data-action="nav-tasks"${onAccount?'':' aria-current="page"'} aria-label="Задания">${icon('grid',21)}<span>Задания</span>${tasksCount?`<span class="nav-badge">${tasksCount}</span>`:''}</button><button class="nav-item${onAccount?' active':''}" type="button" data-action="nav-account"${onAccount?' aria-current="page"':''} aria-label="Личный кабинет">${icon('user',21)}<span>Кабинет</span></button></nav>`;}
function renderApp(){let content=renderTaskHome();if(state.view==='account')content=renderAccount();if(state.view==='intro')content=renderIntro();if(state.view==='rewards')content=renderRewards();if(state.view==='ageGate')content=renderAgeGate();if(state.view==='instructions')content=renderInstructions();return `<div class="app-shell">${renderAppHeader()}<main class="app-main">${content}${renderLegalFooter()}</main>${renderBottomNav()}</div>`;}
/* Модалка живёт отдельно от оболочки: открытие/закрытие окна не перерисовывает
   экран под ней — контент не «мигает» и не проигрывает анимацию заново. */
function setModalBodyClass(){try{document.body.classList.toggle('modal-open',!!state.modal);}catch{}}
/* Правовая модалка доступна на любом экране (даже на гейте, до входа в приложение) */
function syncModal(){const modalType=state.modal&&state.modal.type;const html=(state.mode==='app'||modalType==='legal'||modalType==='terms'||modalType==='privacy')?renderModal():'';let host=document.getElementById('modal-root');if(html){if(!host){host=document.createElement('div');host.id='modal-root';document.body.appendChild(host);}host.innerHTML=html;}else if(host){host.remove();}}
function render(){setModalBodyClass();if(state.mode==='gate'){app.innerHTML=renderGate();syncModal();state.dir='none';return;}if(state.mode==='rejected'){app.innerHTML=renderRejected();syncModal();state.dir='none';return;}app.innerHTML=renderApp();syncModal();state.dir='none';}
function renderModalOnly(){setModalBodyClass();syncModal();}
function closeModal(){if(!state.modal)return;const overlay=document.querySelector('#modal-root .modal-overlay');if(overlay&&!overlay.classList.contains('is-closing')&&motionOK()){state.modal.closing=true;overlay.classList.add('is-closing');window.setTimeout(()=>{if(state.modal&&state.modal.closing){state.modal=null;renderModalOnly();}},260);}else{state.modal=null;renderModalOnly();}}
function go(view){if(state.view===view)return;state.history.push(state.view);state.view=view;state.dir='forward';scrollTopInstant();render();}
function back(){const previous=state.history.pop();state.view=previous||'tasks';state.dir=previous?'back':'none';scrollTopInstant();render();}
function addTaskToProgress(rewardId){const reward=rewards[rewardId]||rewards.small;const taskId=`reviews-${reward.id}`;if(!state.activeTasks.find(task=>task.id===taskId)){state.activeTasks.unshift({id:taskId,title:'Отзывы',rewardId:reward.id,createdAt:Date.now(),stage:'progress'});}saveActiveTasks(state.activeTasks);haptic('success');showToast('Задание добавлено в личный кабинет');}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;switch(action){
case 'eligible-yes':state.mode='rejected';scrollTopInstant();render();break;
case 'eligible-no':{if(!state.consent){haptic('warning');showToast('Сначала отметьте согласие с документами сервиса');const block=document.getElementById('consent-block');if(block){block.classList.remove('is-attention');void block.offsetWidth;block.classList.add('is-attention');try{block.scrollIntoView({block:'nearest',behavior:motionOK()?'smooth':'auto'});}catch{}}break;}persistConsent();persistAccess();state.mode='app';state.view='tasks';state.history=[];state.modal=null;scrollTopInstant();render();break;}
case 'open-terms':haptic('light');state.modal={type:'terms'};renderModalOnly();break;
case 'open-privacy':haptic('light');state.modal={type:'privacy'};renderModalOnly();break;
case 'toggle-consent':{state.consent=!!target.checked;if(state.consent){haptic('light');const block=document.getElementById('consent-block');if(block)block.classList.remove('is-attention');}break;}
case 'back-to-gate':state.mode='gate';scrollTopInstant();render();break;
case 'nav-tasks':state.mode='app';state.view='tasks';state.history=[];state.modal=null;scrollTopInstant();render();break;
case 'nav-account':state.mode='app';state.view='account';state.history=[];state.modal=null;scrollTopInstant();render();break;
case 'locked-soon':haptic('light');showToast('Этот раздел откроется позже');break;
case 'open-legal':haptic('light');state.modal={type:'legal'};renderModalOnly();break;
case 'open-reviews':go('intro');break;
case 'back-step':back();break;
case 'to-rewards':go('rewards');break;
case 'choose-reward':{const rewardId=target.dataset.reward||'small';if(rewardId==='large'){state.selectedReward='large';go('ageGate');}else{state.selectedReward=rewardId;go('instructions');}break;}
case 'age-yes':go('instructions');break;
case 'age-no':haptic('error');showToast('Этот вариант доступен только с 18 лет');break;
case 'start-task':addTaskToProgress(target.dataset.reward||state.selectedReward||'small');render();break;
case 'task-done':{const taskId=target.dataset.task||'';const task=activeTaskById(taskId);if(!task){showToast('Задание не найдено, обнови страницу');break;}state.modal={type:taskStage(task)==='under-review'?'waiting':'done',taskId};renderModalOnly();break;}
case 'done-yes':state.modal={type:'review',taskId:state.modal&&state.modal.taskId||'',draft:state.modal&&state.modal.draft||''};renderModalOnly();break;
case 'done-no':state.modal={type:'wait',taskId:state.modal&&state.modal.taskId||''};renderModalOnly();break;
case 'submit-review':{const modal=state.modal||{};const task=activeTaskById(modal.taskId);if(!task){state.modal=null;render();break;}const field=document.querySelector('#review-text');const text=String(field&&field.value||'').trim();if(!reviewIsValid(text)){haptic('error');showToast(`Опиши отзыв чуть подробнее — минимум ${REVIEW_MIN_LENGTH} символов`);if(field)field.focus();break;}task.review=text.slice(0,1200);task.reviewAt=Date.now();task.stage='under-review';saveActiveTasks(state.activeTasks);haptic('success');state.modal={type:'waiting',taskId:task.id};render();break;}
case 'close-modal':if(target.classList.contains('modal-overlay')&&event.target!==target)break;closeModal();break;
default:break;}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();});
document.addEventListener('input',event=>{if(state.modal&&state.modal.type==='review'&&event.target&&event.target.id==='review-text')state.modal.draft=event.target.value;});
/* Лёгкая вибрация при нажатии на интерактивные элементы (в Telegram) */
document.addEventListener('pointerdown',event=>{try{if(event.target&&event.target.closest&&event.target.closest('.button,.task-card,.reward-option,.nav-item,.icon-button,.header-brand,.header-profile-button,.locked-card,.modal-close,.legal-trigger,.consent-link,.legal-doc-card,.consent-check'))haptic('light');}catch{}},{capture:true,passive:true});
/* Жест «свайп от левого края вправо» = вернуться назад, как в нативных приложениях */
let edgeSwipe=null;
function canSwipeBack(){return state.mode==='app'&&!state.modal&&state.history.length>0;}
document.addEventListener('touchstart',event=>{edgeSwipe=null;if(!canSwipeBack())return;const touch=event.touches&&event.touches[0];if(touch&&touch.clientX<=28)edgeSwipe={x:touch.clientX,y:touch.clientY,dx:0,dy:0};},{passive:true});
document.addEventListener('touchmove',event=>{if(!edgeSwipe)return;const touch=event.touches&&event.touches[0];if(!touch)return;edgeSwipe.dx=touch.clientX-edgeSwipe.x;edgeSwipe.dy=touch.clientY-edgeSwipe.y;if(edgeSwipe.dx<=0||Math.abs(edgeSwipe.dy)>edgeSwipe.dx)return;const main=document.querySelector('.app-main');if(!main)return;main.style.transition='none';main.style.transform=`translateX(${Math.min(edgeSwipe.dx*0.55,96)}px)`;main.style.opacity=String(Math.max(0.55,1-edgeSwipe.dx/380));},{passive:true});
function endEdgeSwipe(){if(!edgeSwipe)return;const dx=edgeSwipe.dx,dy=edgeSwipe.dy;edgeSwipe=null;const main=document.querySelector('.app-main');if(main){main.style.transition='transform 200ms cubic-bezier(0.22,1,0.36,1), opacity 200ms ease';main.style.transform='';main.style.opacity='';window.setTimeout(()=>{main.style.transition='';},230);}if(dx>72&&Math.abs(dy)<64&&canSwipeBack())back();}
document.addEventListener('touchend',endEdgeSwipe,{passive:true});
document.addEventListener('touchcancel',endEdgeSwipe,{passive:true});
/* Шторка модалки тянется вниз пальцем (за «ручку» или за верхнюю часть) */
let sheetDrag=null;
document.addEventListener('pointerdown',event=>{sheetDrag=null;const sheet=event.target&&event.target.closest&&event.target.closest('.modal-sheet');if(!sheet)return;const fromGrabber=!!event.target.closest('.modal-grabber');if(!fromGrabber){if(event.target.closest('textarea,input,button,a'))return;if(sheet.scrollTop>0)return;}sheetDrag={sheet,id:event.pointerId,startY:event.clientY,dy:0,active:false};});
document.addEventListener('pointermove',event=>{if(!sheetDrag||event.pointerId!==sheetDrag.id)return;sheetDrag.dy=event.clientY-sheetDrag.startY;if(sheetDrag.dy>10){sheetDrag.active=true;sheetDrag.sheet.classList.remove('snap-back');sheetDrag.sheet.style.transition='none';sheetDrag.sheet.style.transform=`translateY(${sheetDrag.dy}px)`;}});
function endSheetDrag(){if(!sheetDrag)return;const sheet=sheetDrag.sheet,dy=sheetDrag.dy,active=sheetDrag.active;sheetDrag=null;if(!active)return;if(dy>110){sheet.style.transform='';closeModal();}else{sheet.classList.add('snap-back');sheet.style.transform='';window.setTimeout(()=>{sheet.classList.remove('snap-back');sheet.style.transition='';},260);}}
document.addEventListener('pointerup',endSheetDrag);
document.addEventListener('pointercancel',endSheetDrag);
function renderFatal(error){const message=error&&(error.message||String(error))||'Неизвестная ошибка';const target=app||document.body;target.innerHTML=`<div class="gate-screen"><main class="gate-main"><div class="gate-kicker">Что-то пошло не так</div><h1 class="gate-title">Приложение<br /><em>не загрузилось</em></h1><p class="gate-description">Проверь интернет-соединение и обнови страницу. Если ошибка повторится, открой Mini App заново из Telegram.</p><p class="gate-description">Код ошибки: ${escapeHTML(message)}</p><button class="button button-dark button-full" type="button" onclick="location.reload()">Обновить страницу</button></main></div>`;}
try{render();}catch(error){renderFatal(error);}